'use strict';
const $=id=>document.getElementById(id), $$=sel=>[...document.querySelectorAll(sel)];
const state={apps:[],sessions:[],view:'dashboard',resume:'',analysis:null,interview:null,draftKind:'outreach'};
const statuses=['Saved','Preparing','Applied','Recruiter Screen','Interview','Offer','Rejected','Withdrawn'];
let activeResumeReviewId=null,activeResumeReviewRecord=null;
function ensureResumeReviewPanel(){let panel=$('resumeReviewPanel');if(!panel){panel=document.createElement('section');panel.id='resumeReviewPanel';panel.className='panel';panel.style.marginTop='18px';panel.innerHTML='<div class="panel-head"><div><div class="eyebrow">SAVED RESUME REVIEWS</div><h2>Your evidence decisions</h2><p>Open a saved job-specific resume review or return to Role Intelligence to create one.</p></div></div><div id="resumeReviewHistory" class="history-list"><div class="muted">Loading saved reviews…</div></div>'; $('analysisResult').parentElement.insertAdjacentElement('afterend',panel)}return panel}
function renderResumeReview(report,record=null){record=record||activeResumeReviewRecord;const panel=ensureResumeReviewPanel(),reqs=report.requirements||[],strong=reqs.filter(x=>x.status==='Evidence found'),gaps=reqs.filter(x=>x.status!=='Evidence found');activeResumeReviewRecord=record;activeResumeReviewId=record?.id||null;const decisions=new Map((record?.decisions||[]).map(x=>[x.item_id,x]));panel.innerHTML=`<div class="panel-head"><div><div class="eyebrow">RESUME IMPROVEMENT INTELLIGENCE</div><h2>Review the evidence before editing</h2><p>CareerOS keeps your source resume intact. Confirm each requirement with a concrete example before using it in an application.</p></div><span class="pill-label">${report.mode==='local heuristic'?'LOCAL FALLBACK':'ANALYSIS'}</span></div><div class="dashboard-grid"><div><h3>Terms found in your resume</h3><p>${strong.length?strong.map(x=>`<span class="tag">${esc(x.skill)}</span>`).join(' '):'No matching terms identified.'}</p><small>Keyword presence is not proof of proficiency. Link each claim to a project, work example, or credential.</small></div><div><h3>Evidence gaps to review</h3><p>${gaps.length?gaps.map(x=>`<span class="tag">${esc(x.skill)}</span>`).join(' '):'No gaps identified by this analysis.'}</p><small>Only add a skill or claim after you can support it with real evidence.</small></div></div><h3 style="margin-top:20px">Requirement evidence review</h3>${reqs.map(x=>{const d=decisions.get(x.id)||{};return `<div class="requirement-row"><div><b>${esc(x.skill)}</b><small>${esc(x.evidence||'Evidence not assessed')}<br>${esc(x.action||'')}</small><label class="field-label">Your evidence note (optional)<textarea rows="2" maxlength="6000" data-review-note="${esc(x.id)}">${esc(d.edited_text||'')}</textarea></label></div><label class="field-label">Your review<select data-review-decision="${esc(x.id)}"><option value="">Choose…</option><option value="confirm" ${d.decision==='confirm'?'selected':''}>I can support this</option><option value="reject" ${d.decision==='reject'?'selected':''}>This is not accurate for me</option><option value="edit" ${d.decision==='edit'?'selected':''}>Add a corrected note</option></select></label></div>`}).join('')}<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:16px"><button class="button button-primary" id="saveResumeReview">${record?'Save evidence review':'Save private review'}</button><span class="muted">Your original resume is preserved; these notes do not alter it.</span></div><div class="panel-head" style="margin-top:24px"><div><h3>Saved resume reviews</h3><p>Reopen a saved review later or remove it from your account.</p></div></div><div id="resumeReviewHistory" class="history-list"><div class="muted">Loading saved reviews…</div></div>`;$('saveResumeReview').onclick=async()=>{const items=[];for(const select of panel.querySelectorAll('[data-review-decision]')){const item_id=select.dataset.reviewDecision,decision=select.value;if(!decision)continue;items.push({item_id,decision,edited_text:panel.querySelector(`[data-review-note="${item_id}"]`).value,candidate_confirmed:decision==='confirm'})}const btn=$('saveResumeReview');btn.disabled=true;try{if(!activeResumeReviewId){const input=state.analysisInput;if(!input)throw Error('Run a job analysis before saving this review.');const created=await api('/resume-reviews',{method:'POST',body:JSON.stringify({role:input.role,company:'',jd:input.jd,resume:input.resume,report})});activeResumeReviewId=created.id}const result=await api('/resume-reviews/'+activeResumeReviewId,{method:'PUT',body:JSON.stringify({decisions:items})});if(!result.saved)throw Error('Review was not saved');activeResumeReviewRecord={id:activeResumeReviewId,decisions:result.decisions};toast('Resume evidence review saved');await loadResumeReviews()}catch(e){toast(e.message)}finally{btn.disabled=false}}}
async function loadResumeReviews(){const panel=$('resumeReviewHistory');if(!panel)return;panel.innerHTML='<div class="muted">Loading saved reviews…</div>';try{const rows=await api('/resume-reviews');panel.innerHTML=rows.length?rows.map(r=>`<article class="history-item"><div><b>${esc(r.role)}${r.company?' · '+esc(r.company):''}</b><small>Updated ${esc(r.updated_at)}</small></div><button class="button button-secondary button-sm" data-review-open="${r.id}">Open</button><button class="button button-secondary button-sm" data-review-delete="${r.id}">Delete</button></article>`).join(''):'<div class="empty-state"><b>No saved resume reviews</b><p>Analyze a job and save the review to preserve your requirement evidence decisions.</p></div>';panel.querySelectorAll('[data-review-open]').forEach(b=>b.onclick=async()=>{try{const d=await api('/resume-reviews/'+b.dataset.reviewOpen);$('analysisJD').value=d.jd;$('resumeText').value=d.resume;$('analysisRole').value=d.role;state.analysisInput={jd:d.jd,resume:d.resume,role:d.role};state.analysis=d.report;renderAnalysis(d.report);renderResumeReview(d.report,d)}catch(e){toast(e.message)}});panel.querySelectorAll('[data-review-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('Delete this saved resume review and its private source text?'))return;try{await api('/resume-reviews/'+b.dataset.reviewDelete,{method:'DELETE'});if(activeResumeReviewId===Number(b.dataset.reviewDelete)){activeResumeReviewId=null;activeResumeReviewRecord=null;if(state.analysis)renderResumeReview(state.analysis)}await loadResumeReviews();toast('Resume review deleted')}catch(e){toast(e.message)}})}catch(e){panel.innerHTML=`<div class="empty-state">${esc(e.message)}<button class="button button-secondary button-sm" id="retryResumeReviews">Retry</button></div>`;$('retryResumeReviews').onclick=loadResumeReviews}}
const resumeReviewObserver=new MutationObserver(()=>{if(state.analysis){renderResumeReview(state.analysis);renderResumeEditWorkflow(activeResumeReviewRecord);loadResumeReviews()}});
if($('analysisResult'))resumeReviewObserver.observe($('analysisResult'),{childList:true});
if($('runAnalysis'))$('runAnalysis').addEventListener('click',()=>{activeResumeReviewId=null;activeResumeReviewRecord=null},true);
$$('.nav-item[data-view="intelligence"]').forEach(b=>b.addEventListener('click',()=>{ensureResumeReviewPanel();loadResumeReviews()}));
document.addEventListener('click',e=>{if(e.target?.id==='generateResumeSuggestions'&&activeResumeReviewRecord?.edits?.length&&!confirm('Generating new suggestions replaces the saved suggestion set. Continue?')){e.preventDefault();e.stopImmediatePropagation()}},true);
function renderResumeEditWorkflow(record=null,loadedEdits=null){const panel=$('resumeReviewPanel');if(!panel)return;let box=$('resumeEditWorkflow');if(!box){box=document.createElement('section');box.id='resumeEditWorkflow';panel.querySelector('#resumeReviewHistory')?.insertAdjacentElement('beforebegin',box)}const edits=loadedEdits||record?.edits||[];const finalText=record?.final_resume||'';const finalized=!!record?.finalized_at;box.innerHTML=`<div class="panel-head"><div><div class="eyebrow">REVIEWABLE RESUME EDITS</div><h3>Build a candidate-approved copy</h3><p>Suggestions are not applied until you accept them. Any changed claim requires your factual confirmation. Your original resume stays separate.</p></div><button class="button button-secondary button-sm" id="generateResumeSuggestions">Generate suggestions</button></div><p class="muted" id="resumeSuggestionMode">${edits.length?'Review each source line, proposed text, and required confirmation.':'Save this analysis, then generate reviewable changes. If AI is unavailable, the editor opens with source lines for manual revision.'}</p><div id="resumeEditItems" class="history-list">${edits.length?edits.map(e=>`<article class="history-item resume-edit-item"><div><b>${esc(e.related_requirement||'Unmapped resume content')}</b><small>${esc(e.reason||'')}</small><p><b>Original</b><br><span>${esc(e.original_text||'')}</span></p><label class="field-label">Proposed text<textarea data-proposed="${esc(e.edit_id)}" rows="3" maxlength="6000">${esc(e.proposed_text||'')}</textarea></label><label class="field-label">Decision<select data-edit-decision="${esc(e.edit_id)}"><option value="pending" ${e.decision==='pending'?'selected':''}>Pending</option><option value="accept" ${e.decision==='accept'?'selected':''}>Accept</option><option value="reject" ${e.decision==='reject'?'selected':''}>Reject</option></select></label><label><input type="checkbox" data-edit-confirm="${esc(e.edit_id)}" ${e.candidate_confirmed?'checked':''}> I confirm this edited statement is factually accurate</label></article>`).join(''):'<div class="empty-state">No suggested edits yet. Generate suggestions from this saved resume review.</div>'}</div><div id="finalResumeArea" class="hidden"><label class="field-label">Final approved resume<textarea id="finalResumePreview" rows="14" readonly>${esc(finalText)}</textarea></label></div><div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:12px"><button class="button button-secondary" id="acceptAllResumeEdits" ${edits.length?'':'disabled'}>Accept all shown</button><button class="button button-secondary" id="restoreOriginalResume" ${edits.length?'':'disabled'}>Restore original</button><button class="button button-primary" id="saveApprovedResume" ${edits.length?'':'disabled'}>Save approved resume</button><button class="button button-secondary" id="exportResumeDocx" ${finalized?'':'disabled'}>Export DOCX</button><button class="button button-secondary" id="exportResumeTxt" ${finalized?'':'disabled'}>Export TXT</button></div><p class="muted">DOCX and plain text export are available. PDF export is not implemented.</p>`;if(finalized)$('finalResumeArea').classList.remove('hidden');$('generateResumeSuggestions').onclick=generateResumeSuggestions;$('acceptAllResumeEdits').onclick=()=>{box.querySelectorAll('[data-edit-decision]').forEach(x=>x.value='accept');box.querySelectorAll('[data-edit-confirm]').forEach(x=>x.checked=true)};$('restoreOriginalResume').onclick=()=>{for(const e of edits){const text=box.querySelector(`[data-proposed="${e.edit_id}"]`);const decision=box.querySelector(`[data-edit-decision="${e.edit_id}"]`);const confirm=box.querySelector(`[data-edit-confirm="${e.edit_id}"]`);if(text)text.value=e.original_text;if(decision)decision.value='reject';if(confirm)confirm.checked=false}};$('saveApprovedResume').onclick=saveApprovedResume;$('exportResumeDocx').onclick=()=>downloadApprovedResume('docx');$('exportResumeTxt').onclick=()=>downloadApprovedResume('txt')}
async function ensureResumeReviewSaved(){if(activeResumeReviewId)return activeResumeReviewId;const input=state.analysisInput;if(!input||!state.analysis)throw Error('Run role analysis before generating resume edits.');const record=await api('/resume-reviews',{method:'POST',body:JSON.stringify({role:input.role,company:'',jd:input.jd,resume:input.resume,report:state.analysis})});activeResumeReviewId=record.id;activeResumeReviewRecord={...record,jd:input.jd,resume:input.resume};return activeResumeReviewId}
async function generateResumeSuggestions(){const button=$('generateResumeSuggestions');button.disabled=true;button.textContent='Reviewing source lines…';try{const id=await ensureResumeReviewSaved();const result=await api(`/resume-reviews/${id}/suggestions`,{method:'POST'});const record=await api(`/resume-reviews/${id}`);activeResumeReviewRecord=record;renderResumeEditWorkflow(record,result.edits);$('resumeSuggestionMode').textContent=result.mode==='AI suggestion'?'AI suggestions require candidate fact checking and explicit approval.':'AI is not configured; the local fallback provides source-line editing without inventing rewritten achievements.';toast('Resume suggestions are ready for review')}catch(e){toast(e.message)}finally{button.disabled=false;button.textContent='Generate suggestions'}}
async function saveApprovedResume(){if(!activeResumeReviewId){toast('Save this review before approving resume edits');return}const box=$('resumeEditWorkflow'),edits=[];for(const select of box.querySelectorAll('[data-edit-decision]')){const edit_id=select.dataset.editDecision;edits.push({edit_id,proposed_text:box.querySelector(`[data-proposed="${edit_id}"]`).value,decision:select.value==='pending'?'reject':select.value,candidate_confirmed:box.querySelector(`[data-edit-confirm="${edit_id}"]`).checked})}const button=$('saveApprovedResume');button.disabled=true;try{const result=await api(`/resume-reviews/${activeResumeReviewId}/edits`,{method:'PUT',body:JSON.stringify({edits})});activeResumeReviewRecord={...activeResumeReviewRecord,edits:result.edits,final_resume:result.final_resume,finalized_at:result.finalized_at};$('finalResumePreview').value=result.final_resume;$('finalResumeArea').classList.remove('hidden');$('exportResumeDocx').disabled=false;$('exportResumeTxt').disabled=false;toast('Candidate-approved resume copy saved')}catch(e){toast(e.message)}finally{button.disabled=false}}
async function downloadApprovedResume(format){try{const token=localStorage.getItem('careeros_token');const response=await fetch(`/api/resume-reviews/${activeResumeReviewId}/export.${format}`,{headers:token?{Authorization:'Bearer '+token}:{}});if(!response.ok){const problem=await response.json().catch(()=>({}));throw Error(problem.detail||'Resume export failed')}const blob=await response.blob(),url=URL.createObjectURL(blob),anchor=document.createElement('a'),disposition=response.headers.get('Content-Disposition')||'',match=disposition.match(/filename="([^"]+)"/);anchor.href=url;anchor.download=match?match[1]:`careeros-resume.${format}`;anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Approved resume exported')}catch(e){toast(e.message)}}
const api=async(path,opts={})=>{const token=localStorage.getItem('careeros_token');const r=await fetch('/api'+path,{...opts,headers:{...(opts.body&&!(opts.body instanceof FormData)?{'Content-Type':'application/json'}:{}),...(token?{'Authorization':'Bearer '+token}:{}),...(opts.headers||{})}});let d=await r.json().catch(()=>({detail:'Unexpected server response'}));const detail=Array.isArray(d.detail)?d.detail.map(x=>x.msg||'Invalid value').join('; '):d.detail;if(!r.ok)throw Error(detail||'Request failed');return d};
function toast(msg){const t=$('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2800)}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function dateToday(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function formatDate(d){if(!d)return '—';const dt=new Date(d+'T12:00:00');return dt.toLocaleDateString(undefined,{day:'2-digit',month:'short',year:'numeric'})}
function navigate(view){state.view=view;$$('.view').forEach(x=>x.classList.toggle('active',x.id==='view-'+view));$$('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.view===view));const titles={dashboard:'Overview',applications:'Applications',intelligence:'Role intelligence',interview:'Voice interview',studio:'Career studio',profile:'Career profile',evidence:'Evidence graph'};$('pageTitle').textContent=titles[view]||view; $('sidebar').classList.remove('open');window.scrollTo({top:0,behavior:'smooth'});if(view==='applications')renderApps();if(view==='interview')loadSessions();if(view==='evidence')loadEvidence();if(view==='studio')loadPortfolio()}
$$('[data-view]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.view)));
$('menuBtn').addEventListener('click',()=>$('sidebar').classList.toggle('open'));
async function loadEvidence(){try{const rows=await api('/evidence'+($('evidenceFilter').value?'?kind='+encodeURIComponent($('evidenceFilter').value):''));$('evidenceList').innerHTML=rows.length?rows.map(x=>`<article class="history-item"><div><b>${esc(x.title)}</b><small>${esc(x.kind)} | ${esc(x.source)} | ${x.verified?'Verified by you':'Unverified'}</small><p>${esc(x.detail||'')}</p>${(x.links||[]).map(u=>`<a href="${esc(u)}" target="_blank" rel="noopener noreferrer">Supporting source:</a>`).join(' ')}</div><button class="button button-secondary button-sm" data-evidence-delete="${x.id}">Delete</button></article>`).join(''):'<div class="empty-state"><b>No evidence saved yet</b><p>Add a real skill, project or credential with its source.</p></div>';$('evidenceList').querySelectorAll('[data-evidence-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('Delete this evidence item?'))return;try{await api('/evidence/'+b.dataset.evidenceDelete,{method:'DELETE'});toast('Evidence deleted');loadEvidence()}catch(e){toast(e.message)}});await loadRoleMaps()}catch(e){$('evidenceList').innerHTML=`<div class="empty-state">${esc(e.message)}</div>`}}
$('evidenceFilter').onchange=loadEvidence;
async function loadRoleMaps(){try{const [maps,evidence]=await Promise.all([api('/role-maps'),api('/evidence')]);$('roleMapsList').innerHTML=maps.length?maps.map(m=>`<article class="history-item"><div><b>${esc(m.role)}${m.company?' | '+esc(m.company):''}</b><small>Saved ${esc(m.created_at)} | ${m.requirements.length} requirements</small><p>${esc(m.summary||'Saved job requirements')}</p>${m.requirements.map(r=>`<div class="requirement-row"><div><b>${esc(r.skill)}</b><small>${esc(r.importance||'')}${r.status?'Suggested: '+esc(r.status):''}<br>${esc(r.evidence_summary||'No resume evidence note')}${r.action?' | '+esc(r.action):''}</small><div class="placeholder-tags">${r.evidence_links.map(l=>`<span>${esc(l.title)}${l.verified?' verified':''}<button class="text-button" data-unlink="${m.id}:${r.id}:${l.evidence_id}" aria-label="Unlink ${esc(l.title)}">x</button></span>`).join('')}</div><div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:8px"><select aria-label="Evidence for ${esc(r.skill)}" id="linkSelect-${r.id}"><option value="">Choose evidence to link</option>${evidence.map(x=>`<option value="${x.id}">${esc(x.title)} (${esc(x.kind)}${x.verified?', verified':''})</option>`).join('')}</select><button class="button button-secondary button-sm" data-link="${m.id}:${r.id}">Link evidence</button></div></div></div>`).join('')}<button class="button button-secondary button-sm" data-delete-map="${m.id}">Delete role map</button></article>`).join(''):'<div class="empty-state"><b>No saved role maps</b><p>Analyze a job description and save its requirements to start linking evidence.</p></div>';$('roleMapsList').querySelectorAll('[data-link]').forEach(b=>b.onclick=async()=>{const [mapId,reqId]=b.dataset.link.split(':'),select=$('linkSelect-'+reqId);if(!select.value){toast('Choose an evidence item first');return}try{await api(`/role-maps/${mapId}/requirements/${reqId}/evidence`,{method:'POST',body:JSON.stringify({evidence_id:Number(select.value)})});toast('Evidence linked to requirement');loadRoleMaps()}catch(e){toast(e.message)}});$('roleMapsList').querySelectorAll('[data-unlink]').forEach(b=>b.onclick=async()=>{const [mapId,reqId,evidenceId]=b.dataset.unlink.split(':');try{await api(`/role-maps/${mapId}/requirements/${reqId}/evidence/${evidenceId}`,{method:'DELETE'});toast('Evidence link removed');loadRoleMaps()}catch(e){toast(e.message)}});$('roleMapsList').querySelectorAll('[data-delete-map]').forEach(b=>b.onclick=async()=>{if(!confirm('Delete this role map and its evidence links?'))return;try{await api('/role-maps/'+b.dataset.deleteMap,{method:'DELETE'});toast('Role map deleted');loadRoleMaps()}catch(e){toast(e.message)}})}catch(e){$('roleMapsList').innerHTML=`<div class="empty-state">${esc(e.message)}</div>`}}

$('evidenceForm').onsubmit=async e=>{e.preventDefault();const link=$('evidenceLinks').value.trim();try{await api('/evidence',{method:'POST',body:JSON.stringify({kind:$('evidenceKind').value,title:$('evidenceTitle').value.trim(),detail:$('evidenceDetail').value.trim(),source:'user-entered',verified:$('evidenceVerified').checked,links:link?[link]:[]})});e.target.reset();toast('Evidence saved');loadEvidence()}catch(err){toast(err.message)}};
let portfolioEditId=null;
async function loadPortfolio(){try{const [cases,projects]=await Promise.all([api('/portfolio'),api('/evidence?kind=project')]);const select=$('portfolioEvidence'),selected=select.value;select.innerHTML='<option value="">No project linked</option>'+projects.map(p=>`<option value="${p.id}">${esc(p.title)}</option>`).join('');if(projects.some(p=>String(p.id)===selected))select.value=selected;$('portfolioList').innerHTML=cases.length?cases.map(c=>`<article class="history-item"><div><b>${esc(c.title)}</b><small>Updated ${esc(c.updated_at)}${c.evidence_id?' ? linked to project evidence':''}</small><p>${esc(c.content.slice(0,220))}${c.content.length>220?'...':''}</p></div><div style="display:flex;gap:6px"><button class="button button-secondary button-sm" data-open-portfolio="${c.id}">Open</button><button class="button button-secondary button-sm" data-delete-portfolio="${c.id}">Delete</button></div></article>`).join(''):'<div class="empty-state"><b>No saved case studies yet</b><p>Generate a portfolio draft, review it, then save it here.</p></div>';$('portfolioList').querySelectorAll('[data-open-portfolio]').forEach(b=>b.onclick=()=>{const c=cases.find(x=>String(x.id)===b.dataset.openPortfolio);portfolioEditId=c.id;$('draftType').value='portfolio';state.draftKind='portfolio';$('portfolioTitle').value=c.title;$('draftOutput').value=c.content;$('portfolioEvidence').value=c.evidence_id||'';$('draftPanel').classList.remove('hidden');$('draftPanel').scrollIntoView({behavior:'smooth'})});$('portfolioList').querySelectorAll('[data-delete-portfolio]').forEach(b=>b.onclick=async()=>{if(!confirm('Delete this saved case study?'))return;try{await api('/portfolio/'+b.dataset.deletePortfolio,{method:'DELETE'});toast('Case study deleted');loadPortfolio()}catch(e){toast(e.message)}})}catch(e){$('portfolioList').innerHTML=`<div class="empty-state">${esc(e.message)}</div>`}}
$('savePortfolio').onclick=async()=>{if(state.draftKind!=='portfolio'){toast('Choose Portfolio case study as the draft type before saving');return}const title=$('portfolioTitle').value.trim(),content=$('draftOutput').value.trim(),ref=$('portfolioEvidence').value;try{const saved=await api('/portfolio'+(portfolioEditId?'/'+portfolioEditId:''),{method:portfolioEditId?'PUT':'POST',body:JSON.stringify({title,content,evidence_id:ref||null})});portfolioEditId=saved.id;toast('Portfolio case study saved');loadPortfolio()}catch(e){toast(e.message)}};


async function loadApps(){try{state.apps=await api('/applications');renderDashboard();renderApps();loadOutcomes()}catch(e){toast(e.message)}}
async function loadSessions(){try{state.sessions=await api('/interviews');renderHistory();renderDashboard();loadOutcomes()}catch(e){}}
async function loadOutcomes(){const box=$('outcomeInsights');if(!box)return;box.innerHTML='<div class="muted">Loading saved outcomes?</div>';try{const data=await api('/outcomes');const stages=Object.entries(data.application_stages||{}).filter(([,n])=>n>0).map(([name,n])=>`${esc(name)}: ${n}`).join(' ? ');const gaps=(data.evidence_gaps||[]).map(x=>`<li><b>${esc(x.skill)}</b> ? recorded ${x.count} time(s)${x.actions?.length?`; ${esc(x.actions.join(' ? '))}`:''}</li>`).join('');const coaching=(data.repeated_coaching_gaps||[]).map(x=>`<li>${esc(x.recommendation)} <span class="muted">(${x.count} answers)</span></li>`).join('');const content=[stages?`<p><b>Application stages:</b> ${stages}</p>`:'',gaps?`<p><b>Repeated evidence gaps</b></p><ul>${gaps}</ul>`:'',coaching?`<p><b>Recurring interview coaching</b></p><ul>${coaching}</ul>`:''].filter(Boolean).join('');box.innerHTML=content?`${content}<small class="muted">${esc(data.notice||'Based on your saved records.')}</small>`:`<p class="muted">No patterns yet. Save an application, role requirement map, or completed practice interview to build your personal outcome history.</p><small class="muted">${esc(data.notice||'')}</small>`;}catch(e){box.innerHTML=`<div class="muted">Outcome insights could not be loaded. <button type="button" class="btn ghost" id="retryOutcomes">Retry</button></div>`;const retry=$('retryOutcomes');if(retry)retry.onclick=loadOutcomes}}
function renderDashboard(){const apps=state.apps;const active=apps.filter(a=>!['Rejected','Withdrawn','Offer'].includes(a.status));const due=apps.filter(a=>a.follow_up_date&&a.follow_up_date<=dateToday()&&!['Rejected','Withdrawn','Offer'].includes(a.status));const upcoming=apps.filter(a=>a.interview_date&&a.interview_date>=dateToday()&&!['Rejected','Withdrawn'].includes(a.status)).sort((a,b)=>a.interview_date.localeCompare(b.interview_date));$('metricActive').textContent=active.length;$('metricDue').textContent=due.length;$('metricDueHint').textContent=due.filter(a=>a.follow_up_date<dateToday()).length+' overdue ? includes today';$('metricInterviews').textContent=upcoming.length;const profileFields=['name','target_roles','skills','location','career_goal','resume_text','education','project_descriptions'];$('metricEvidence').textContent=Math.round(profileFields.filter(k=>String(savedProfile[k]||'').trim()).length/profileFields.length)+'%';$('appCount').textContent=apps.length;
 const queue=apps.map(a=>({...a,next_action:a.next_action||(a.interview_date&&a.interview_date>=dateToday()?'Prepare for scheduled interview':''),follow_up_date:a.follow_up_date||(a.interview_date&&a.interview_date>=dateToday()?a.interview_date:'')})).filter(a=>a.next_action||a.follow_up_date).sort((a,b)=>(a.follow_up_date||'9999').localeCompare(b.follow_up_date||'9999')).slice(0,5);$('actionQueue').innerHTML=queue.length?queue.map(a=>{const overdue=a.follow_up_date&&a.follow_up_date<dateToday();return `<div class="action-row"><div class="action-date ${overdue?'overdue':''}"><b>${a.follow_up_date?new Date(a.follow_up_date+'T12:00:00').getDate():'—'}</b><small>${a.follow_up_date?new Date(a.follow_up_date+'T12:00:00').toLocaleDateString(undefined,{month:'short'}):'ACTION'}</small></div><div class="action-detail"><b>${esc(a.next_action||'Review application status')}</b><small>${esc(a.company)} · ${esc(a.role)}</small></div><button class="icon-button" data-edit="${a.id}" title="Edit">↗</button></div>`}).join(''):`<div class="empty-state"><div class="empty-symbol">◷</div><b>Your next move starts here</b><p>Add an opportunity to create your first action.</p><button class="button button-secondary" id="emptyAdd">Add opportunity</button></div>`;
 const counts={Saved:0,Applied:0,Interview:0,Offer:0};apps.forEach(a=>{if(a.status==='Saved'||a.status==='Preparing')counts.Saved++;if(['Applied','Recruiter Screen'].includes(a.status))counts.Applied++;if(a.status==='Interview')counts.Interview++;if(a.status==='Offer')counts.Offer++});$('pipelineStages').innerHTML=[['Saved','saved'],['Applied','applied'],['Interview','interview'],['Offer','offer']].map(([k,c])=>`<div class="stage"><span class="stage-dot ${c}"></span><label>${k}</label><b>${counts[k]}</b></div>`).join('');const events=[...apps.map(a=>({date:a.created_at,label:'Added opportunity',detail:a.company+' | '+a.role})),...state.sessions.map(s=>({date:s.created_at,label:'Completed interview practice',detail:s.role+(s.company?' | '+s.company:'')}))].sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))).slice(0,6);$('recentActivity').innerHTML=events.length?events.map(x=>`<div class="history-item"><div><b>${esc(x.label)}</b><small>${esc(x.detail)} ? ${esc(formatDate(String(x.date||'').slice(0,10)))}</small></div></div>`).join(''):'<div class="muted">Applications and completed practice sessions will show up here.</div>';$('actionQueue').querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openModal(state.apps.find(a=>a.id==b.dataset.edit)));const ea=$('emptyAdd');if(ea)ea.onclick=()=>openModal();}
function renderApps(){const search=($('appSearch')?.value||'').toLowerCase(),status=$('statusFilter')?.value||'',priority=$('priorityFilter')?.value||'';const filtered=state.apps.filter(a=>(!search||[a.company,a.role,a.location,a.next_action,a.notes,a.recruiter_name,a.recruiter_email,a.job_description].join(' ').toLowerCase().includes(search))&&(!status||a.status===status)&&(!priority||a.priority===priority));const sort=$('appSort')?.value||'updated';filtered.sort((a,b)=>sort==='company'?a.company.localeCompare(b.company):sort==='applied'?(b.applied_date||'').localeCompare(a.applied_date||''):sort==='followup'?(a.follow_up_date||'9999').localeCompare(b.follow_up_date||'9999'):b.updated_at.localeCompare(a.updated_at));$('applicationRows').innerHTML=filtered.map(a=>`<tr><td><div class="company-cell"><b>${esc(a.company)}</b><small>${esc(a.role)}${a.location?' | '+esc(a.location):''}</small></div></td><td><span class="status-chip ${esc(a.status)}">${esc(a.status)}</span></td><td>${a.interview_date?formatDate(a.interview_date):'\u2014'}</td><td>${a.follow_up_date?`<span class="${a.follow_up_date<dateToday()?'due-date':''}">${formatDate(a.follow_up_date)}</span>`:'?'}</td><td>${esc(a.recruiter_name||'\u2014')}</td><td>${esc(a.next_action||'?')}</td><td><span class="priority ${esc(a.priority)}">? ${esc(a.priority)}</span></td><td><div class="table-actions"><button class="icon-button" data-edit="${a.id}" title="Edit">?</button><button class="icon-button" data-delete="${a.id}" title="Delete">?</button></div></td></tr>`).join('');$('appEmpty').classList.toggle('hidden',filtered.length>0);$('applicationRows').querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openModal(state.apps.find(a=>a.id==b.dataset.edit)));$('applicationRows').querySelectorAll('[data-delete]').forEach(b=>b.onclick=async()=>{if(confirm('Delete this application record?')){try{await api('/applications/'+b.dataset.delete,{method:'DELETE'});toast('Application deleted');loadApps()}catch(e){toast(e.message)}}});}
['appSearch','statusFilter','priorityFilter','appSort'].forEach(id=>$(id).addEventListener('input',renderApps));
function openModal(app=null){$('applicationForm').reset();$('editId').value=app?.id||'';$('modalTitle').textContent=app?'Edit opportunity':'Add opportunity';$('formCompany').value=app?.company||'';$('formRole').value=app?.role||'';$('formLocation').value=app?.location||'';$('formUrl').value=app?.job_url||'';$('formStatus').value=app?.status||'Saved';$('formPriority').value=app?.priority||'Normal';$('formApplied').value=app?.applied_date||'';$('formInterview').value=app?.interview_date||'';$('formRecruiter').value=app?.recruiter_name||'';$('formRecruiterEmail').value=app?.recruiter_email||'';$('formDescription').value=app?.job_description||'';$('formFollowup').value=app?.follow_up_date||'';$('formNextAction').value=app?.next_action||'';$('formNotes').value=app?.notes||'';$('appModal').classList.remove('hidden')}
function closeModal(){$('appModal').classList.add('hidden')}
$('quickAdd').onclick=$('addApplication').onclick=()=>openModal();$('closeModal').onclick=$('cancelModal').onclick=closeModal;$('appModal').addEventListener('click',e=>{if(e.target===$('appModal'))closeModal()});$('applicationForm').onsubmit=async e=>{e.preventDefault();const p={company:$('formCompany').value.trim(),role:$('formRole').value.trim(),location:$('formLocation').value,job_url:$('formUrl').value,status:$('formStatus').value,priority:$('formPriority').value,applied_date:$('formApplied').value,interview_date:$('formInterview').value,recruiter_name:$('formRecruiter').value,recruiter_email:$('formRecruiterEmail').value,job_description:$('formDescription').value,follow_up_date:$('formFollowup').value,next_action:$('formNextAction').value,notes:$('formNotes').value};try{const id=$('editId').value;await api('/applications'+(id?'/'+id:''),{method:id?'PUT':'POST',body:JSON.stringify(p)});closeModal();toast(id?'Application updated':'Opportunity added');await loadApps()}catch(err){toast(err.message)}};
$('resumeFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;$('resumeName').textContent=f.name;const fd=new FormData();fd.append('file',f);try{const r=await fetch('/api/parse-resume',{method:'POST',headers:{'Authorization':'Bearer '+(localStorage.getItem('careeros_token')||'')},body:fd});const d=await r.json();if(!r.ok)throw Error(d.detail);$('resumeText').value=d.text;state.resume=d.text;$('resumeName').textContent=`${f.name} · ${d.characters.toLocaleString()} chars extracted`;toast('Resume text extracted')}catch(err){toast(err.message)}};
$('runAnalysis').onclick=async()=>{const jd=$('analysisJD').value.trim(),resume=$('resumeText').value.trim(),role=$('analysisRole').value.trim()||'Target role';if(!jd){toast('Paste a job description first');return}state.resume=resume;$('runAnalysis').disabled=true;$('runAnalysis').textContent='Analyzing evidence…';try{const d=await api('/analyze',{method:'POST',body:JSON.stringify({jd,resume,role})});state.analysis=d;state.analysisInput={jd,resume,role};renderAnalysis(d)}catch(e){toast(e.message)}finally{$('runAnalysis').disabled=false;$('runAnalysis').innerHTML='Analyze role & evidence <span>→</span>'}};
function renderAnalysis(d){const r=d.requirements||[];$('analysisResult').innerHTML=`<div class="result-content"><div class="eyebrow">YOUR ROLE DNA</div><h2>Evidence map</h2><div class="result-summary">${esc(d.summary||'Requirements mapped against the information you supplied.')}</div><div class="result-stats"><b>${r.length}</b> requirements identified</div><h3>Requirement → evidence</h3>${r.map(x=>`<div class="requirement-row"><div><b>${esc(x.skill)}</b><small>${esc(x.evidence||'Evidence not assessed')}<br>${esc(x.action||'')}</small></div><span class="evidence-tag ${x.status==='Evidence found'?'':'gap'}">${esc(x.status||'Review')}</span></div>`).join('')}<h3>Recommended actions</h3><ul class="result-list">${(d.recommendations||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>Interview focus</h3><div class="placeholder-tags">${(d.interview_focus||[]).map(x=>`<span>${esc(x)}</span>`).join('')}</div><div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:18px"><button class="button button-secondary" id="saveRoleMap">Save requirements to Evidence Graph</button><button class="button button-primary" style="margin-top:18px" id="useAnalysis">Use this JD in Voice Interview →</button></div></div>`;$('saveRoleMap').onclick=async()=>{const input=state.analysisInput;if(!input){toast('Run an analysis before saving requirements');return}try{await api('/role-maps',{method:'POST',body:JSON.stringify({role:input.role,company:'',jd:input.jd,summary:d.summary||'',requirements:r})});toast('Requirements saved to Evidence Graph');navigate('evidence')}catch(e){toast(e.message)}};$('useAnalysis').onclick=()=>{$('interviewJD').value=$('analysisJD').value;$('interviewResume').value=$('resumeText').value;$('interviewRole').value=$('analysisRole').value;navigate('interview');toast('Role context transferred')}};
$$('input[name="mode"]').forEach(r=>r.addEventListener('change',()=>$$('.mode-card').forEach(c=>c.classList.toggle('selected',c.querySelector('input').checked))));
function buildQuestions(jd,resume,role){const terms=extractTerms(jd),skills=terms.length?terms:['role fundamentals','problem solving','communication'];const project=(resume.match(/(?:project|built|developed|created|implemented)[^\n.]{10,110}/i)||[])[0]||'one of your projects';const tech=skills.slice(0,7);const q=[];const add=(cat,text)=>q.push({category:cat,text});
add('INTRODUCTION','Walk me through your background and how it connects to this '+role+' opportunity.');add('MOTIVATION','Why are you interested in this role and our type of work?');add('MOTIVATION','What would you like to learn or contribute in your first six months?');add('PROJECT DEEP DIVE',`Choose a project from your resume and explain the problem, your contribution, and the outcome.`);add('PROJECT DEEP DIVE',`Walk me through the architecture or workflow of ${project}.`);add('PROJECT DEEP DIVE','What was the most difficult technical or analytical decision you made in that project?');add('PROJECT DEEP DIVE','How did you validate the quality and correctness of your project?');add('PROJECT DEEP DIVE','If you had another week, what would you improve and why?');for(let i=0;i<7;i++){const s=tech[i%tech.length];const prompts=[`Explain a core concept in ${s} and when you would use it.`,`Describe a practical task you would solve using ${s}.`,`What common mistake or limitation should a beginner understand about ${s}?`,`How would you troubleshoot a problem involving ${s}?`,`How would you explain ${s} to a non-technical stakeholder?`,`Compare two approaches or tools relevant to ${s}.`,`What evidence from your experience demonstrates your understanding of ${s}?`];add('TECHNICAL · '+s,prompts[i])}
add('ROLE SCENARIO',`You receive an urgent task related to ${skills[0]}. How would you clarify the requirement and plan your work?`);add('ROLE SCENARIO','A result looks incorrect shortly before a deadline. What steps do you take to investigate and communicate it?');add('ROLE SCENARIO','You disagree with a teammate about an approach. How would you resolve the decision?');add('ROLE SCENARIO','Describe how you would prioritize two competing tasks with limited time.');add('BEHAVIORAL','Tell me about a time you learned something difficult independently.');add('BEHAVIORAL','Describe a mistake or setback and what you changed afterward.');add('BEHAVIORAL','How do you respond to constructive feedback?');add('BEHAVIORAL','What kind of team environment helps you do your best work?');add('CLOSING','What questions would you ask the hiring team about this role?');add('CLOSING','Is there anything about your experience or motivation you would like to add?');return q.slice(0,25)}
function extractTerms(t){const terms=['Python','SQL','Excel','Power BI','Tableau','Pandas','NumPy','DAX','ETL','PostgreSQL','MySQL','Django','FastAPI','REST APIs','Git','Docker','AWS','React','JavaScript','statistics','data visualization','data cleaning','business analysis','communication','stakeholder management','machine learning','networking','Linux','SIEM','incident response','problem solving','testing','API design'];return terms.filter(x=>new RegExp('\\b'+x.replace(/[.*+?^${}()|[\\]\\]/g,'\\$&')+'\\b','i').test(t))}
function voiceCheck(){const ok=!!(window.SpeechRecognition||window.webkitSpeechRecognition),syn=!!window.speechSynthesis;$('voiceSupport').textContent=ok&&syn?'Speech recognition and voice playback are available in this browser.':'Voice recognition may not be supported here. Text answers and question playback fallback are available.'}
voiceCheck();
$('startInterview').onclick=async()=>{const jd=$('interviewJD').value.trim(),resume=$('interviewResume').value.trim(),role=$('interviewRole').value.trim()||'Target role';if(!jd&&!resume){toast('Add a job description or resume evidence for a personalized interview');return}state.resume=resume;const mode=document.querySelector('input[name="mode"]:checked').value,company=$('interviewCompany').value.trim(),interviewType=$('interviewType').value,difficulty=$('interviewDifficulty').value,duration=Number($('interviewDuration').value),btn=$('startInterview');btn.disabled=true;btn.textContent='Preparing personalized questions?';let questions,questionMode='local question blueprint';try{const prepared=await api('/interviews/questions',{method:'POST',body:JSON.stringify({role,company,jd,resume,interview_type:interviewType,difficulty})});if(prepared.questions?.length===25){questions=prepared.questions;questionMode=prepared.mode}}catch(e){btn.disabled=false;btn.innerHTML='Start 25-question practice <span>?</span>';toast(e.message);return}if(!questions)questions=buildQuestions(jd,resume,role);state.interview={role,company,jd,resume,mode,interviewType,difficulty,duration,questionMode,questions,index:0,followupCount:0,answers:[],recognition:null,recording:false};btn.disabled=false;btn.innerHTML='Start 25-question practice <span>?</span>';$('interviewLive').classList.remove('hidden');$('interviewReport').classList.add('hidden');$('liveRoleTitle').textContent=role+(company?' | '+company:'');$('sessionModeLabel').textContent=(mode==='coach'?'Coach mode':'Real interview')+' | '+difficulty+' | '+duration+' min';navigate('interview');$('interviewLive').scrollIntoView({behavior:'smooth',block:'start'});showQuestion()};
function showQuestion(){const s=state.interview;if(!s)return;const q=s.questions[s.index];$('questionProgress').textContent=`Question ${s.index+1} of ${s.questions.length}`;$('progressBar').style.width=((s.index)/s.questions.length*100)+'%';$('questionCategory').textContent=q.category;$('currentQuestion').textContent=q.text;$('questionHint').textContent=s.mode==='coach'?'Answer naturally. Feedback will appear after you submit.':'Take a moment to organize your thoughts. Your answers will be evaluated at the end.';$('answerText').value='';$('instantFeedback').classList.add('hidden');$('submitAnswer').textContent=s.index===s.questions.length-1?'Finish interview & view report →':'Submit answer & continue →';speak(q.text)}
function speak(text){if(!window.speechSynthesis)return;window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.rate=.96;u.pitch=1;u.onstart=()=>{};window.speechSynthesis.speak(u)}
$('speakQuestion').onclick=()=>state.interview&&speak(state.interview.questions[state.interview.index].text);
$('recordAnswer').onclick=()=>{const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){toast('Speech recognition is not supported. Type your answer instead.');return}if(state.interview.recognition){try{state.interview.recognition.stop()}catch{} }const rec=new SR();rec.lang='en-IN';rec.continuous=true;rec.interimResults=true;let finalText=$('answerText').value.trim();rec.onresult=e=>{let interim='';for(let i=e.resultIndex;i<e.results.length;i++){const txt=e.results[i][0].transcript;if(e.results[i].isFinal)finalText+=(finalText?' ':'')+txt;else interim+=txt} $('answerText').value=(finalText+(interim?' '+interim:'' )).trim()};rec.onerror=e=>{$('recordingState').textContent='Voice issue: '+e.error+' · type your answer';$('recordAnswer').disabled=false;$('stopRecording').disabled=true};rec.onend=()=>{$('recordAnswer').disabled=false;$('stopRecording').disabled=true;$('recordingState').textContent='Voice capture stopped';state.interview.recording=false};state.interview.recognition=rec;state.interview.recording=true;$('recordAnswer').disabled=true;$('stopRecording').disabled=false;$('recordingState').textContent='Listening… speak now';try{rec.start()}catch(e){toast('Could not start microphone. Check browser permission.')}};
$('stopRecording').onclick=()=>{if(state.interview?.recognition)state.interview.recognition.stop()};
async function evaluateAnswer(q,answer){try{return await api('/feedback',{method:'POST',body:JSON.stringify({question:q.text,answer,context:state.interview.jd+'\nResume evidence: '+state.interview.resume})})}catch{return {score:null,label:'Saved for review',strengths:[],improvements:['Feedback service unavailable. Review your transcript and try again.'],sample:''}}}
async function maybeFollowup(q,answer,feedback){const s=state.interview;if(!answer||s.followupCount>=5)return null;const weak=answer.split(/\s+/).length<35||(feedback.improvements||[]).some(x=>/expand|specific example|explain why|clarify|support/i.test(x));if(!weak)return null;try{const r=await api('/interviews/followup',{method:'POST',body:JSON.stringify({question:q.text,answer,context:s.jd+'\nRole: '+s.role+'\nResume evidence: '+s.resume})});return r.follow_up?{category:'FOLLOW-UP',text:r.follow_up}:null}catch(e){toast('Could not generate an adaptive follow-up; continuing with the prepared questions.');return null}}
$('submitAnswer').onclick=async()=>{const s=state.interview;if(!s)return;if(s.recording&&s.recognition){try{s.recognition.stop()}catch{}s.recording=false}const q=s.questions[s.index],answer=$('answerText').value.trim();$('submitAnswer').disabled=true;$('submitAnswer').textContent='Evaluating…';const ev=await evaluateAnswer(q,answer);const followup=await maybeFollowup(q,answer,ev);if(followup){s.questions.splice(s.index+1,0,followup);s.followupCount=(s.followupCount||0)+1}s.answers.push({question:q.text,category:q.category,answer,feedback:ev,skipped:!answer});$('submitAnswer').disabled=false;if(s.mode==='coach'){renderFeedback(ev);if(s.index<s.questions.length-1){$('submitAnswer').textContent='Continue to next question →';$('submitAnswer').onclick=nextQuestion;return}else{$('submitAnswer').onclick=finishInterview;$('submitAnswer').textContent='Finish interview & view report →';return}}if(s.index<s.questions.length-1){nextQuestion()}else finishInterview()};
function renderFeedback(ev){$('instantFeedback').classList.remove('hidden');$('instantFeedback').innerHTML=`<div class="feedback-score">${ev.score==null?'—':ev.score+' / 100'}</div><h3>${esc(ev.label||'Answer feedback')}</h3><b style="font-size:11px">What worked</b><ul>${(ev.strengths||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><b style="font-size:11px">Improve next time</b><ul>${(ev.improvements||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${ev.sample?`<p><b>Structure to try:</b> ${esc(ev.sample)}</p>`:''}<button class="button button-secondary button-sm" id="feedbackContinue">Next question →</button>`;$('feedbackContinue').onclick=nextQuestion}
function nextQuestion(){const s=state.interview;if(!s)return;s.index++;if(s.index<s.questions.length){$('submitAnswer').onclick=async()=>{const q=s.questions[s.index],answer=$('answerText').value.trim();$('submitAnswer').disabled=true;$('submitAnswer').textContent='Evaluating…';const ev=await evaluateAnswer(q,answer);const followup=await maybeFollowup(q,answer,ev);if(followup){s.questions.splice(s.index+1,0,followup);s.followupCount=(s.followupCount||0)+1}s.answers.push({question:q.text,category:q.category,answer,feedback:ev,skipped:!answer});$('submitAnswer').disabled=false;if(s.mode==='coach'){renderFeedback(ev);$('submitAnswer').onclick=nextQuestion;$('submitAnswer').textContent='Continue to next question →'}else nextQuestion()};showQuestion()}else finishInterview()}
$('skipQuestion').onclick=()=>{const s=state.interview;if(!s)return;s.answers.push({question:s.questions[s.index].text,category:s.questions[s.index].category,answer:'',feedback:{score:0,label:'Skipped',strengths:[],improvements:['Practice this question in a future session.']},skipped:true});if(s.index<s.questions.length-1)nextQuestion();else finishInterview()};
$('endInterview').onclick=()=>{if(confirm('End this interview now and create a report from completed answers?'))finishInterview(true)};
async function finishInterview(early=false){const s=state.interview;if(!s)return;if(s.recognition)try{s.recognition.stop()}catch{}window.speechSynthesis?.cancel();const answers=s.answers;const scored=answers.filter(a=>typeof a.feedback?.score==='number'&&!a.skipped);const avg=scored.length?Math.round(scored.reduce((n,a)=>n+a.feedback.score,0)/scored.length):null;const improve=[...new Set(answers.flatMap(a=>a.feedback?.improvements||[]))].slice(0,8);const report={role:s.role,company:s.company,mode:s.mode,interviewType:s.interviewType,difficulty:s.difficulty,duration:s.duration,questionMode:s.questionMode,planned:s.questions.length,completed:answers.length,early,averageScore:avg,answers,improvementPlan:improve,createdAt:new Date().toISOString()};try{await api('/interviews'+(s.sessionId?'/'+s.sessionId:''),{method:s.sessionId?'PUT':'POST',body:JSON.stringify({role:s.role,company:s.company,mode:s.mode,resume:s.resume,jd:s.jd,status:'completed',report})});toast('Interview report saved')}catch(e){toast('Report created; could not save to server: '+e.message)}renderReport(report);$('progressBar').style.width='100%';$('interviewLive').classList.add('hidden');$('interviewReport').classList.remove('hidden');$('interviewReport').scrollIntoView({behavior:'smooth'});state.interview=null;loadSessions()}
function renderReport(r){const answers=r.answers||[];$('interviewReport').innerHTML=`<div class="report-head"><div><div class="eyebrow">SESSION COMPLETE · CAREEROS VOICE</div><h2>${esc(r.role)} ${r.company?'· '+esc(r.company):''}</h2><p>${r.completed} of ${r.planned||25} primary questions · ${r.followupsCompleted||r.followups_completed||0} adaptive follow-ups · ${r.mode==='coach'?'Coach mode':'Real interview'} ${r.early?'· Ended early':''}</p></div><div class="report-score">${r.averageScore==null?'—':r.averageScore+'%'}<small style="display:block;font:500 9px 'DM Sans';color:#999">practice estimate</small></div></div><div class="report-columns"><div class="report-section"><h3>What to work on next</h3><ul>${(r.improvementPlan||[]).map(x=>`<li>${esc(x)}</li>`).join('')||'<li>Complete more answers to build a focused plan.</li>'}</ul></div><div class="report-section"><h3>Session overview</h3><p style="font-size:11px;color:#777">Answered: ${answers.filter(a=>a.answer).length}<br>Skipped: ${answers.filter(a=>a.skipped).length}<br>Evaluation: ${answers.some(a=>a.feedback?.mode==='AI')?'AI-assisted':'Local coaching heuristic'}</p><button class="button button-secondary button-sm" id="exportReport">Export session JSON ↓</button></div></div><h3 style="margin-top:23px">Question-by-question review</h3>${answers.map((a,i)=>`<div class="report-question"><b>${i+1}. ${esc(a.question)}</b><p><b>Answer:</b> ${esc(a.answer||'Skipped')}</p><p><b>Feedback:</b> ${esc((a.feedback?.improvements||[]).join(' ')||a.feedback?.label||'Review this response.')}</p></div>`).join('')}<div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:20px"><button class="button button-primary" id="newInterview">Start another interview →</button><button class="button button-secondary" id="backToProfile">Refine role evidence</button></div>`;$('exportReport').onclick=()=>download('careeros-interview-report.json',JSON.stringify(r,null,2),'application/json');$('newInterview').onclick=()=>{$('interviewReport').classList.add('hidden');navigate('interview')};$('backToProfile').onclick=()=>navigate('intelligence')}
function renderHistory(){$('sessionHistory').innerHTML=state.sessions.length?state.sessions.map(s=>`<div class="history-item"><div><b>${esc(s.role||'Interview')} ${s.company?'· '+esc(s.company):''}</b><small>${esc(s.mode)} · ${formatDate(s.created_at?.slice(0,10))}</small></div><button class="text-button" data-session="${s.id}">View report ↗</button></div>`).join(''):'<div class="muted">No saved sessions yet. Start a voice interview to build your practice history.</div>';$('sessionHistory').querySelectorAll('[data-session]').forEach(b=>b.onclick=async()=>{try{const d=await api('/interviews/'+b.dataset.session);renderReport(d.report);$('interviewReport').classList.remove('hidden');$('interviewReport').scrollIntoView({behavior:'smooth'})}catch(e){toast(e.message)}})}$('refreshSessions').onclick=loadSessions;
$$('[data-draft]').forEach(b=>b.onclick=()=>{portfolioEditId=null;state.draftKind=b.dataset.draft;$('draftType').value=state.draftKind;$('draftPanel').classList.remove('hidden');$('draftTitle').textContent={outreach:'Recruiter outreach',resume:'Resume evidence improvements',portfolio:'Portfolio case study'}[state.draftKind];$('draftPanel').scrollIntoView({behavior:'smooth'})});$('closeDraft').onclick=()=>$('draftPanel').classList.add('hidden');$('draftType').onchange=()=>{state.draftKind=$('draftType').value;$('draftTitle').textContent=$('draftType').selectedOptions[0].textContent};$('generateDraft').onclick=async()=>{const btn=$('generateDraft');btn.disabled=true;btn.textContent='Building draft…';try{const d=await api('/draft',{method:'POST',body:JSON.stringify({kind:state.draftKind,context:$('draftContext').value,resume:$('draftResume').value,jd:$('draftJD').value})});$('draftOutput').value=d.content;toast('Draft generated · '+d.mode)}catch(e){toast(e.message)}finally{btn.disabled=false;btn.textContent='Generate grounded draft'}};$('copyDraft').onclick=async()=>{try{await navigator.clipboard.writeText($('draftOutput').value);toast('Draft copied')}catch{ $('draftOutput').select();document.execCommand('copy');toast('Draft copied')}};
function download(name,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)}
$('settingsBtn').onclick=logoutCareerOS;$('logoutProfile').onclick=logoutCareerOS;$('onboardingLogout').onclick=logoutCareerOS;async function logoutCareerOS(){if(!confirm('Sign out of this CareerOS account on this device?'))return;try{await api('/auth/logout',{method:'POST'})}catch(e){toast('Could not confirm server sign-out; clearing this device session.')}finally{localStorage.removeItem('careeros_token');localStorage.removeItem('careeros_email');state.apps=[];state.sessions=[];location.reload()}}
