async function init(){if(!localStorage.getItem('careeros_token')){$('authGate').classList.remove('hidden');$('profileOnboardingGate').classList.add('hidden');$('appShell').inert=true;$('appShell').setAttribute('aria-hidden','true');return} $('authGate').classList.add('hidden');$('systemStatus').textContent='Private account workspace';try{const h=await api('/health');if(h.ai_configured)$('systemStatus').textContent='AI configured';$('voiceBadge').textContent=h.realtime_configured?'LIVE VOICE CONFIGURED':'TEXT PRACTICE AVAILABLE';$('realtimeStatus').textContent=h.realtime_configured?'Live AI voice is configured. Microphone permission is required.':'Realtime provider is not configured. Use the clearly labeled turn-based practice mode.';}catch{$('voiceBadge').textContent='? VOICE STATUS UNKNOWN';}try{const profile=await loadProfile();if(!profile.profile_complete){$('appShell').inert=true;$('appShell').setAttribute('aria-hidden','true');$('profileOnboardingGate').classList.remove('hidden');$('onboardName').focus();return}}catch(e){if(e.message.includes('Sign in')){localStorage.removeItem('careeros_token');localStorage.removeItem('careeros_email');$('authGate').classList.remove('hidden');return}toast('Could not load your profile. Retry or check your connection.');return}$('profileOnboardingGate').classList.add('hidden');$('appShell').inert=false;$('appShell').removeAttribute('aria-hidden');await loadApps();await loadSessions()}
