// WebRTC-based realtime voice session (ephemeral credential only; provider secret stays server-side).
let livePeer=null,liveChannel=null,liveMic=null,liveTranscript=[],liveMeta=null;
$('startRealtimeInterview').onclick=async()=>{
 const btn=$('startRealtimeInterview'),status=$('realtimeStatus');const role=$('interviewRole').value.trim()||'Target role',jd=$('interviewJD').value.trim(),resume=$('interviewResume').value.trim();
 if(!jd){toast('Paste the actual job description first for a tailored live interview');return}
 btn.disabled=true;btn.textContent='Connecting live interviewer…';status.textContent='Requesting a short-lived voice session credential…';
 try{
  const cfg=await api('/realtime/session',{method:'POST',body:JSON.stringify({role,company:$('interviewCompany').value,jd,resume})});
  liveMic=await navigator.mediaDevices.getUserMedia({audio:true});livePeer=new RTCPeerConnection();liveMic.getTracks().forEach(t=>livePeer.addTrack(t,liveMic));
  livePeer.ontrack=e=>{let audio=$('realtimeAudio');if(!audio){audio=document.createElement('audio');audio.id='realtimeAudio';audio.autoplay=true;audio.style.display='none';document.body.appendChild(audio)}audio.srcObject=e.streams[0];audio.play().catch(()=>status.textContent='Tap the page once to enable interviewer audio.')};
  liveChannel=livePeer.createDataChannel('oai-events');liveChannel.onmessage=ev=>{try{const msg=JSON.parse(ev.data);if(msg.type==='conversation.item.input_audio_transcription.completed'&&msg.transcript)liveTranscript.push({speaker:'candidate',text:msg.transcript,at:new Date().toISOString()});else if(msg.type==='response.audio_transcript.done'&&msg.transcript)liveTranscript.push({speaker:'interviewer',text:msg.transcript,at:new Date().toISOString()});else if(msg.type==='response.output_text.done'&&msg.text)liveTranscript.push({speaker:'interviewer',text:msg.text,at:new Date().toISOString()})}catch{}};liveChannel.onopen=()=>{liveChannel.send(JSON.stringify({type:'response.create',response:{instructions:'Begin now. Greet the candidate, briefly explain the interview, then ask the first resume/JD-specific question. Speak naturally and ask only one question at a time.'}}));status.textContent='Live AI interview connected · microphone active'};
  const offer=await livePeer.createOffer();await livePeer.setLocalDescription(offer);
  const call=await fetch('https://api.openai.com/v1/realtime/calls',{method:'POST',headers:{Authorization:'Bearer '+cfg.client_secret,'Content-Type':'application/sdp'},body:offer.sdp});
  if(!call.ok)throw Error('Realtime connection failed ('+call.status+'). Check model/API access and try again.');
  await livePeer.setRemoteDescription({type:'answer',sdp:await call.text()});
  liveTranscript=[];liveMeta={role,company:$('interviewCompany').value,mode:'realtime',resume,jd};btn.classList.add('hidden');$('stopRealtimeInterview').classList.remove('hidden');
 }catch(e){status.textContent=e.message;toast('Live voice could not connect');if(livePeer){livePeer.close();livePeer=null}if(liveMic){liveMic.getTracks().forEach(t=>t.stop());liveMic=null}btn.disabled=false;btn.textContent='Start live AI voice interview ◉'}
};
$('stopRealtimeInterview').onclick=async()=>{if(liveMeta&&liveTranscript.length){const report={role:liveMeta.role,company:liveMeta.company,mode:'Realtime voice',planned:null,completed:liveTranscript.filter(x=>x.speaker==='candidate').length,transcript:liveTranscript,createdAt:new Date().toISOString(),note:'Realtime audio transcript events captured where browser/provider transcription was available. Review transcript accuracy.'};try{await api('/interviews',{method:'POST',body:JSON.stringify({...liveMeta,report})});toast('Realtime session transcript saved to your private history')}catch(e){toast('Session ended; transcript could not be saved: '+e.message)}}if(liveChannel)liveChannel.close();if(livePeer)livePeer.close();if(liveMic)liveMic.getTracks().forEach(t=>t.stop());liveChannel=null;livePeer=null;liveMic=null;liveMeta=null;liveTranscript=[];$('stopRealtimeInterview').classList.add('hidden');$('startRealtimeInterview').classList.remove('hidden');$('startRealtimeInterview').disabled=false;$('startRealtimeInterview').textContent='Start live AI voice interview ◉';$('realtimeStatus').textContent='Live session ended. The standard 25-question interview and saved transcript remain available.'};

// Career profile: one saved source of truth for personalized workflows.
let savedProfile={};
function profileEvidence(profile=savedProfile){return [['Resume',profile.resume_text],['Verified skills',profile.skills],['Education',profile.education],['Experience',profile.experience],['Certifications',profile.certifications],['Achievements',profile.achievements],['Projects',profile.project_descriptions],['Career goal',profile.career_goal],['Work preferences',profile.work_preferences]].filter(([,v])=>String(v||'').trim()).map(([label,value])=>label+':\n'+value).join('\n\n')}
async function loadProfile(){savedProfile=await api('/profile');$('onboardEmail').value=localStorage.getItem('careeros_email')||'';const fields={profileName:'name',profileRoles:'target_roles',profileLocation:'location',profileWorkMode:'work_mode',profileSkills:'skills',profileGoal:'career_goal',profileEducation:'education',profileGradYear:'graduation_year',profileStage:'career_stage',profileCertifications:'certifications',profileAchievements:'achievements',profileProjects:'project_descriptions',profileExperience:'experience',profilePreferences:'work_preferences',profilePortfolio:'portfolio_url',profileLinkedin:'linkedin_url',profileGithub:'github_url',profileResume:'resume_text',onboardName:'name',onboardStage:'career_stage',onboardGradYear:'graduation_year',onboardEducation:'education',onboardRoles:'target_roles',onboardSkills:'skills',onboardLocation:'location',onboardWorkMode:'work_mode',onboardProjects:'project_descriptions',onboardExperience:'experience',onboardCertifications:'certifications',onboardGithub:'github_url',onboardPortfolio:'portfolio_url'};for(const [id,key] of Object.entries(fields)){if($(id))$(id).value=savedProfile[key]||($(id).tagName==='SELECT'?(key==='work_mode'?'Any':''): '')}state.resume=profileEvidence(savedProfile);if(state.resume){$('resumeText').value||=state.resume;$('interviewResume').value||=state.resume;$('draftResume').value||=state.resume}if(savedProfile.target_roles){$('analysisRole').value||=savedProfile.target_roles.split(',')[0].trim();$('interviewRole').value||=savedProfile.target_roles.split(',')[0].trim()}if(savedProfile.location)$('jobLocation').value||=savedProfile.location;renderDashboard();return savedProfile}
function profileEditorPayload(){return {name:$('profileName').value,target_roles:$('profileRoles').value,location:$('profileLocation').value,work_mode:$('profileWorkMode').value,career_stage:$('profileStage').value,graduation_year:$('profileGradYear').value,skills:$('profileSkills').value,career_goal:$('profileGoal').value,education:$('profileEducation').value,certifications:$('profileCertifications').value,achievements:$('profileAchievements').value,project_descriptions:$('profileProjects').value,experience:$('profileExperience').value,work_preferences:$('profilePreferences').value,portfolio_url:$('profilePortfolio').value,linkedin_url:$('profileLinkedin').value,github_url:$('profileGithub').value,resume_text:$('profileResume').value}}
function onboardingPayload(){const {profile_complete,...profileDraft}=savedProfile;return {...profileDraft,name:$('onboardName').value.trim(),career_stage:$('onboardStage').value,graduation_year:$('onboardGradYear').value.trim(),education:$('onboardEducation').value.trim(),target_roles:$('onboardRoles').value.trim(),skills:$('onboardSkills').value.trim(),location:$('onboardLocation').value.trim(),work_mode:$('onboardWorkMode').value,project_descriptions:$('onboardProjects').value,experience:$('onboardExperience').value,certifications:$('onboardCertifications').value,github_url:$('onboardGithub').value.trim(),portfolio_url:$('onboardPortfolio').value.trim()}}
async function saveProfileDraft(payload){const result=await api('/profile',{method:'PUT',body:JSON.stringify(payload)});savedProfile=result.profile;state.resume=profileEvidence(savedProfile);renderDashboard();return result}
$('saveProfile').onclick=async()=>{try{const result=await saveProfileDraft(profileEditorPayload());$('resumeText').value=state.resume;$('interviewResume').value=state.resume;$('draftResume').value=state.resume;$('profileSavedNote').textContent=result.profile_complete?'Saved just now ? Profile complete':'Saved just now ? Finish the required profile details to unlock all workspace tools';$('profileSavedNote').style.color='#43a98b';toast(result.profile_complete?'Career profile saved':'Profile saved; complete the required fields to continue');if(!result.profile_complete){$('appShell').inert=true;$('appShell').setAttribute('aria-hidden','true');for(const [id,key] of Object.entries({onboardName:'name',onboardStage:'career_stage',onboardGradYear:'graduation_year',onboardEducation:'education',onboardRoles:'target_roles',onboardSkills:'skills',onboardLocation:'location',onboardWorkMode:'work_mode',onboardProjects:'project_descriptions',onboardExperience:'experience',onboardCertifications:'certifications',onboardGithub:'github_url',onboardPortfolio:'portfolio_url'}))$(id).value=savedProfile[key]||'';$('profileOnboardingGate').classList.remove('hidden')}}catch(e){toast(e.message)}};
let onboardingSaveTimer=null,onboardingSaveChain=Promise.resolve();async function persistOnboardingDraft(showMessage=true){const payload=onboardingPayload();onboardingSaveChain=onboardingSaveChain.catch(()=>{}).then(()=>saveProfileDraft(payload));try{const result=await onboardingSaveChain;if(showMessage){$('onboardingStatus').dataset.error='false';$('onboardingStatus').textContent='Progress saved to your private profile.'}return result}catch(e){$('onboardingStatus').dataset.error='true';$('onboardingStatus').textContent='Could not save your progress: '+e.message;throw e}}
$('onboardingForm').addEventListener('input',()=>{clearTimeout(onboardingSaveTimer);onboardingSaveTimer=setTimeout(()=>persistOnboardingDraft(false).catch(()=>{}),700)});$('saveOnboardingDraft').onclick=()=>{clearTimeout(onboardingSaveTimer);persistOnboardingDraft(true).catch(()=>{})};$('onboardingForm').onsubmit=async e=>{e.preventDefault();clearTimeout(onboardingSaveTimer);const button=$('completeOnboarding');button.disabled=true;button.textContent='Saving profile?';$('onboardingStatus').textContent='';try{await persistOnboardingDraft(false);const result=await api('/profile/complete',{method:'POST'});savedProfile=result.profile;$('onboardingStatus').dataset.error='false';$('onboardingStatus').textContent='Profile complete. Loading your private workspace?';$('profileOnboardingGate').classList.add('hidden');$('appShell').inert=false;$('appShell').removeAttribute('aria-hidden');await loadApps();await loadSessions();navigate('dashboard')}catch(err){$('onboardingStatus').dataset.error='true';$('onboardingStatus').textContent=err.message}finally{button.disabled=false;button.textContent='Save and continue ?'}};
$('searchJobs').onclick=async()=>{const q=$('jobQuery').value.trim();if(!q){toast('Enter a role or skill to search');return}const btn=$('searchJobs');btn.disabled=true;btn.textContent='Searching…';$('jobResults').classList.remove('hidden');$('jobResults').innerHTML='<div class="muted">Searching public listings…</div>';try{const params=new URLSearchParams({q,location:$('jobLocation').value,remote:$('jobRemote').checked?'true':'false'});const d=await api('/jobs/search?'+params.toString());$('jobNotice').textContent=d.notice||'External listings · verify at source';$('jobResults').innerHTML=d.results.length?d.results.map((j,i)=>{const url=safeJobUrl(j.url);return `<article class="job-result"><h3>${esc(j.title)}</h3><small>${esc(j.company)} · ${esc(j.location||'Location not specified')}${j.remote?' · Remote':''}</small><div class="job-tags">${(j.tags||[]).slice(0,4).map(t=>`<span>${esc(t)}</span>`).join('')}</div><div class="job-result-actions"><button class="button button-secondary" data-savejob="${i}">＋ Track opportunity</button>${url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">View source ↗</a>`:''}</div></article>`}).join(''):'<div class="muted">No matching listings in this source right now. Try a broader role or location.</div>';$$('[data-savejob]').forEach(b=>b.onclick=async()=>{const j=d.results[Number(b.dataset.savejob)];try{await api('/applications',{method:'POST',body:JSON.stringify({company:j.company||'Company not listed',role:j.title,location:j.location||'',job_url:safeJobUrl(j.url)||'',job_description:j.description||'',status:'Saved',priority:'Normal',next_action:'Review the job description and verify fresher eligibility'})});toast('Opportunity added to your pipeline');await loadApps();b.disabled=true;b.textContent='✓ Added'}catch(e){toast(e.message)}})}catch(e){$('jobResults').innerHTML=`<div class="muted">${esc(e.message)}. You can still add an opportunity manually or use a company career page.</div>`}finally{btn.disabled=false;btn.textContent='Search opportunities →'}};
function safeJobUrl(value){try{const u=new URL(value);return ['http:','https:'].includes(u.protocol)?u.href:''}catch{return ''}}
