$('exportApps').onclick=async()=>{const btn=$('exportApps');btn.disabled=true;try{const token=localStorage.getItem('careeros_token');const response=await fetch('/api/applications/export.csv',{headers:token?{'Authorization':'Bearer '+token}:{}});if(!response.ok){const problem=await response.json().catch(()=>({}));throw Error(problem.detail||'Export failed')}const blob=await response.blob(),url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download='careeros-application-pipeline.csv';anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Application pipeline exported')}catch(e){toast(e.message)}finally{btn.disabled=false}};

// Interview checkpoints stay server-side and are private to the signed-in account.
function interviewSnapshot(s){const question=s.questions[s.index],answered=s.answers.length&&s.answers[s.answers.length-1].question===question?.text;return {session_state:'in_progress',questions:s.questions,index:(answered?Math.min(s.index+1,s.questions.length-1):s.index),answers:s.answers,draftAnswer:answered?'':$('answerText').value,followupCount:s.followupCount,primaryCount:s.primaryCount||25,interviewType:s.interviewType,difficulty:s.difficulty,duration:s.duration,questionMode:s.questionMode,elapsedSeconds:s.startedAt?Math.floor((Date.now()-s.startedAt)/1000):0}}
async function persistInterview(){const s=state.interview;if(!s?.sessionId)return;const report=interviewSnapshot(s);await api('/interviews/'+s.sessionId,{method:'PUT',body:JSON.stringify({role:s.role,company:s.company,mode:s.mode,resume:s.resume,jd:s.jd,status:'in_progress',report})})}
let answerCheckpointTimer;
$('answerText').addEventListener('input',()=>{if(!state.interview?.sessionId)return;clearTimeout(answerCheckpointTimer);answerCheckpointTimer=setTimeout(()=>persistInterview().catch(e=>toast('Could not save the answer draft: '+e.message)),800)});
const originalStartInterview=$('startInterview').onclick;
$('startInterview').onclick=async function(){await originalStartInterview();const s=state.interview;if(!s)return;s.primaryCount=s.questions.filter(q=>q.category!=='FOLLOW-UP').length;s.startedAt=Date.now();try{const saved=await api('/interviews',{method:'POST',body:JSON.stringify({role:s.role,company:s.company,mode:s.mode,resume:s.resume,jd:s.jd,status:'in_progress',report:interviewSnapshot(s)})});s.sessionId=saved.id;await loadSessions()}catch(e){toast('Session recovery could not be enabled: '+e.message)}updateSessionClock();s.timer=setInterval(updateSessionClock,1000)};
function updateSessionClock(){const s=state.interview;if(!s)return;const elapsed=Math.floor((Date.now()-s.startedAt)/1000),target=s.duration*60,mm=n=>String(Math.floor(n/60)).padStart(2,'0'),ss=n=>String(n%60).padStart(2,'0');$('sessionModeLabel').textContent=(s.mode==='coach'?'Coach mode':'Real interview')+' · '+s.difficulty+' · target '+s.duration+'m · elapsed '+mm(elapsed)+':'+ss(elapsed)+(elapsed>=target?' · target time reached':'')}
const originalShowQuestion=showQuestion;
showQuestion=function(){originalShowQuestion();const s=state.interview;if(!s)return;const q=s.questions[s.index],primaryDone=s.answers.filter(a=>a.category!=='FOLLOW-UP').length,primaryCount=s.primaryCount||s.questions.filter(x=>x.category!=='FOLLOW-UP').length;$('questionProgress').textContent=q.category==='FOLLOW-UP'?'Adaptive follow-up · '+primaryDone+' / '+primaryCount+' primary questions':'Primary question '+Math.min(primaryDone+1,primaryCount)+' of '+primaryCount;$('progressBar').style.width=(primaryDone/Math.max(1,primaryCount)*100)+'%'};
const originalRenderFeedback=renderFeedback;
renderFeedback=function(feedback){clearTimeout(answerCheckpointTimer);originalRenderFeedback(feedback);persistInterview().catch(e=>toast('Could not save the interview checkpoint: '+e.message))};
const originalNextQuestion=nextQuestion;
nextQuestion=async function(){clearTimeout(answerCheckpointTimer);const s=state.interview;if(s&&s.index>=s.questions.length-1)return originalNextQuestion();originalNextQuestion();if(state.interview)try{await persistInterview()}catch(e){toast('Could not save the interview checkpoint: '+e.message)}};
const originalFinishInterview=finishInterview;
finishInterview=async function(early=false){clearTimeout(answerCheckpointTimer);const s=state.interview;try{return await originalFinishInterview(early)}finally{if(s?.timer)clearInterval(s.timer)}};
renderHistory=function(){ $('sessionHistory').innerHTML=state.sessions.length?state.sessions.map(s=>`<div class="history-item"><div><b>${esc(s.role||'Interview')} ${s.company?'· '+esc(s.company):''}</b><small>${esc(s.status==='in_progress'?'Interrupted session · resume available':s.mode+' · '+formatDate(s.created_at?.slice(0,10)))}</small></div><button class="text-button" data-session="${s.id}">${s.status==='in_progress'?'Resume':'View report'} ↗</button></div>`).join(''):'<div class="muted">No saved sessions yet. Start an interview to build your practice history.</div>';$$('[data-session]').forEach(b=>b.onclick=async()=>{try{const d=await api('/interviews/'+b.dataset.session);if(d.status==='in_progress'){const saved=d.report||{};state.interview={role:d.role||'Target role',company:d.company||'',mode:d.mode||'coach',resume:d.resume_text||'',jd:d.jd_text||'',interviewType:saved.interviewType||'Mixed',difficulty:saved.difficulty||'Moderate',duration:saved.duration||25,questionMode:saved.questionMode||'recovered session',questions:saved.questions||[],index:Math.min(saved.index||0,(saved.questions||[]).length-1),followupCount:saved.followupCount||0,answers:saved.answers||[],primaryCount:saved.primaryCount||25,startedAt:Date.now()-(saved.elapsedSeconds||0)*1000,sessionId:d.id};$('interviewLive').classList.remove('hidden');$('interviewReport').classList.add('hidden');$('liveRoleTitle').textContent=state.interview.role+(state.interview.company?' | '+state.interview.company:'');navigate('interview');showQuestion();$("answerText").value=saved.draftAnswer||"";updateSessionClock();state.interview.timer=setInterval(updateSessionClock,1000)}else{renderReport(d.report);$('interviewReport').classList.remove('hidden');$('interviewReport').scrollIntoView({behavior:'smooth'})}}catch(e){toast(e.message)}})};
const originalRenderReport=renderReport;
renderReport=function(report){if(Array.isArray(report.answers)){report.primary_planned=25;report.planned=25;report.completed=report.answers.filter(a=>a.category!=='FOLLOW-UP').length;report.followupsCompleted=report.answers.filter(a=>a.category==='FOLLOW-UP').length;report.totalResponses=report.answers.length;if(state.interview?.startedAt)report.elapsedSeconds=Math.floor((Date.now()-state.interview.startedAt)/1000)}originalRenderReport(report);const summary=$('interviewReport').querySelector('.report-head p');if(summary&&Number.isFinite(report.elapsedSeconds)){const seconds=report.elapsedSeconds;summary.textContent+=' · elapsed '+String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0')}};
